    var old = document.getElementById('cal-sync-toast');
    if (old) old.remove();
    var t = document.createElement('div');
    t.id = 'cal-sync-toast';
    t.style.cssText = 'position:fixed;right:20px;bottom:20px;z-index:2147483647;max-width:380px;padding:14px 18px;border-radius:12px;'
